{
  toJson := fun d =>
    (have arr :=
        #[Lean.toJson d.uri, Lean.Json.num (Lean.JsonNumber.fromNat d.pos.line),
          Lean.Json.num (Lean.JsonNumber.fromNat d.pos.character)];
      have __do_jp := fun __r arr =>
        have __do_jp := fun __r arr => Lean.Json.arr arr;
        match d.id? with
        | some id =>
          have arr := arr.push (Lean.toJson id);
          __do_jp () arr
        | x => __do_jp () arr;
      match d.cPos? with
      | some cPos =>
        have arr := arr.push (Lean.toJson cPos);
        __do_jp () arr
      | x => __do_jp () arr).run }

